+  });
+
+  test('lists only uploaded assets compatible with the requested platform', async () => {
+    const list = vi.fn(async () => [
+      { id: 'android-explicit', name: 'build.bin', os: 'android', md5: 'a' },
+      { id: 'android-apk', name: 'com.example.app.apk', md5: 'b' },
